// WANT. — your own free link, with automatic product reading.
// HOW TO DEPLOY (free, about 2 minutes):
// 1. Go to dash.cloudflare.com and sign up / sign in (free plan is enough).
// 2. Workers & Pages -> Create -> Create Worker -> name it "want" -> Deploy.
// 3. Click "Edit code", delete everything, paste this whole file, then Deploy.
// 4. Open the address it gives you (https://want.<your-name>.workers.dev) in Safari on your iPhone,
//    tap Share -> Add to Home Screen. Pasting a product link now fills name, photo and price.
// 5. (Optional, for Apple Pay + bank sync) In the worker: Settings -> Bindings -> Add -> KV namespace ->
//    create one called "want", variable name WANT_KV. Then Settings -> Variables and Secrets -> Add ->
//    type Secret, name WANT_TOKEN, value: a long random key you make up (keep it private). Deploy.
//    Put the same key in WANT. -> Settings -> Connections -> Sync key.
// Your data lives on your phone, in this app. To move data from the old link: Settings -> Copy backup there,
// then Settings -> Restore from backup here.

// ---- product page reader (shared by the worker and the local tests) ----
function decodeEnt(s) {
  return String(s || '')
    .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)));
}
function numPrice(v) {
  if (v == null) return '';
  if (typeof v === 'number') return isFinite(v) && v > 0 ? String(Math.round(v * 100) / 100) : '';
  let s = String(v).replace(/[^\d.,]/g, '');
  if (!s) return '';
  const lc = s.lastIndexOf(','), ld = s.lastIndexOf('.');
  if (lc > -1 && ld > -1) s = lc > ld ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  else if (lc > -1) s = /,\d{1,2}$/.test(s) ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  else if ((s.match(/\./g) || []).length > 1) s = s.replace(/\.(?=.*\.)/g, '');
  const n = parseFloat(s);
  return isFinite(n) && n > 0 ? String(Math.round(n * 100) / 100) : '';
}
const SYM = { '₪': 'ILS', '$': 'USD', '€': 'EUR', '£': 'GBP', '¥': 'JPY' };
function curOf(v) {
  if (!v) return '';
  const s = String(v).trim().toUpperCase();
  if (/^[A-Z]{3}$/.test(s)) return s === 'NIS' ? 'ILS' : s;
  for (const k in SYM) if (String(v).includes(k)) return SYM[k];
  if (/ש"ח|ש״ח|שח/.test(v)) return 'ILS';
  return '';
}
function imgOf(v, base) {
  if (!v) return '';
  if (Array.isArray(v)) return imgOf(v[0], base);
  if (typeof v === 'object') return imgOf(v.url || v.contentUrl || v['@id'], base);
  try { return new URL(decodeEnt(v), base).href; } catch (e) { return ''; }
}
function extract(html, base) {
  const out = { title: '', image: '', price: '', currency: '', store: '', brand: '' };
  const meta = k => {
    const re1 = new RegExp('<meta[^>]+(?:property|name|itemprop)\\s*=\\s*["\']' + k + '["\'][^>]*?content\\s*=\\s*["\']([^"\']*)["\']', 'i');
    const re2 = new RegExp('<meta[^>]+content\\s*=\\s*["\']([^"\']*)["\'][^>]*?(?:property|name|itemprop)\\s*=\\s*["\']' + k + '["\']', 'i');
    const m = html.match(re1) || html.match(re2);
    return m ? decodeEnt(m[1]).trim() : '';
  };
  // 1) structured data (JSON-LD) — most shops publish a Product here
  const isProd = o => { const t = o && o['@type']; return t && (Array.isArray(t) ? t : [t]).some(x => /^(Product|ProductGroup|IndividualProduct|Car|Book|Offer)$/i.test(x)); };
  const fromOffers = off => {
    if (!off) return;
    const list = Array.isArray(off) ? off : [off];
    for (const o of list) {
      if (!o || typeof o !== 'object') continue;
      const p = numPrice(o.price ?? o.lowPrice ?? (o.priceSpecification && (Array.isArray(o.priceSpecification) ? o.priceSpecification[0] : o.priceSpecification).price));
      if (p && !out.price) { out.price = p; out.currency = curOf(o.priceCurrency || (o.priceSpecification && o.priceSpecification.priceCurrency)) || out.currency; }
      if (o.offers) fromOffers(o.offers);
    }
  };
  const seen = new Set();
  const walk = o => {
    if (!o || typeof o !== 'object' || seen.has(o)) return;
    seen.add(o);
    if (Array.isArray(o)) { o.forEach(walk); return; }
    if (isProd(o)) {
      if (!out.title && o.name) out.title = decodeEnt(o.name);
      if (!out.image && o.image) out.image = imgOf(o.image, base);
      if (!out.brand && o.brand) out.brand = decodeEnt(typeof o.brand === 'object' ? o.brand.name : o.brand);
      fromOffers(o.offers);
      if (!out.price && o.price) { out.price = numPrice(o.price); out.currency = curOf(o.priceCurrency); }
      if (o.hasVariant) walk(o.hasVariant);
    }
    for (const k in o) if (k !== 'offers') walk(o[k]);
  };
  for (const m of html.matchAll(/<script[^>]+type\s*=\s*["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)) {
    const raw = m[1].replace(/^\s*<!--|-->\s*$/g, '').replace(/^\s*\/\*<!\[CDATA\[\*\/|\/\*\]\]>\*\/\s*$/g, '').trim();
    try { walk(JSON.parse(raw)); } catch (e) {
      try { walk(JSON.parse(raw.replace(/[\u0000-\u001f]+/g, ' '))); } catch (e2) {}
    }
  }
  // 2) Open Graph / product meta tags
  out.title = out.title || meta('og:title') || meta('twitter:title') || meta('name');
  out.image = out.image || imgOf(meta('og:image:secure_url') || meta('og:image') || meta('twitter:image') || meta('twitter:image:src') || meta('image'), base);
  if (!out.price) {
    const p = meta('product:price:amount') || meta('og:price:amount') || meta('product:sale_price:amount') || meta('price') || meta('twitter:data1');
    if (numPrice(p)) { out.price = numPrice(p); out.currency = curOf(meta('product:price:currency') || meta('og:price:currency') || meta('priceCurrency') || p); }
  }
  if (!out.currency) out.currency = curOf(meta('product:price:currency') || meta('og:price:currency') || meta('priceCurrency'));
  // 3) microdata and common inline JSON
  if (!out.price) {
    const m = html.match(/itemprop\s*=\s*["']price["'][^>]*content\s*=\s*["']([^"']+)["']/i) || html.match(/content\s*=\s*["']([\d.,]+)["'][^>]*itemprop\s*=\s*["']price["']/i);
    if (m) out.price = numPrice(m[1]);
  }
  if (!out.price) {
    const m = html.match(/"(?:price|salePrice|currentPrice|finalPrice)"\s*:\s*"?(\d[\d.,]*)"?/i);
    if (m) out.price = numPrice(m[1]);
    const c = html.match(/"(?:priceCurrency|currency|currencyCode)"\s*:\s*"([A-Z]{3})"/);
    if (c && !out.currency) out.currency = c[1];
  }
  if (!out.price) {
    const m = html.match(/class\s*=\s*["'][^"']*a-offscreen[^"']*["'][^>]*>\s*([^<]{1,30})</i);
    if (m && numPrice(m[1])) { out.price = numPrice(m[1]); out.currency = out.currency || curOf(m[1]); }
  }
  if (!out.image) {
    const m = html.match(/<link[^>]+rel\s*=\s*["']image_src["'][^>]*href\s*=\s*["']([^"']+)["']/i);
    if (m) out.image = imgOf(m[1], base);
  }
  if (!out.title) { const m = html.match(/<title[^>]*>([^<]*)<\/title>/i); if (m) out.title = decodeEnt(m[1]); }
  // tidy
  let host = '';
  try { host = new URL(base).hostname.replace(/^(www|m|shop)\./, ''); } catch (e) {}
  const sn = meta('og:site_name') || meta('application-name');
  out.store = sn || (host ? host.split('.')[0].replace(/^./, c => c.toUpperCase()) : '');
  if (!sn && out.store.length <= 4) out.store = out.store.toUpperCase();
  out.title = out.title.replace(/\s+/g, ' ').trim();
  if (out.store) {
    const esc = out.store.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    out.title = out.title.replace(new RegExp('\\s*[|\\-–—:]\\s*' + esc + '.*$', 'i'), '').replace(new RegExp('^' + esc + '(\\.[a-z.]+)?\\s*[|\\-–—:]\\s*', 'i'), '');
  }
  out.title = out.title.replace(/\s*[|–—]\s*[^|–—]{1,30}$/, m => (out.title.length - m.length > 8 ? '' : m)).slice(0, 120).trim();
  if (!out.currency && out.price && /\.co\.il$|\.il$/.test(host)) out.currency = 'ILS';
  return out;
}

// ---- sync: Apple Pay payments and bank updates waiting for the app ----
// Storage: one KV namespace bound as WANT_KV. Auth: a secret WANT_TOKEN, sent as "Authorization: Bearer <key>".
const JS = (o, st = 200) => new Response(JSON.stringify(o), { status: st, headers: { 'content-type': 'application/json; charset=utf-8', 'access-control-allow-origin': '*', 'cache-control': 'no-store' } });
async function sha(s) { const b = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(s)); return [...new Uint8Array(b)].slice(0, 12).map(x => x.toString(16).padStart(2, '0')).join(''); }
function authed(req, env) {
  const h = req.headers.get('authorization') || '';
  const k = h.replace(/^Bearer\s+/i, '').trim();
  if (!env.WANT_TOKEN || !k || k.length !== env.WANT_TOKEN.length) return false;
  let d = 0; for (let i = 0; i < k.length; i++) d |= k.charCodeAt(i) ^ env.WANT_TOKEN.charCodeAt(i);
  return d === 0;
}
async function kvGet(env, key, dflt) { try { const v = await env.WANT_KV.get(key); return v ? JSON.parse(v) : dflt; } catch (e) { return dflt; } }
const kvPut = (env, key, v) => env.WANT_KV.put(key, JSON.stringify(v));
async function readBody(req) {
  const ct = req.headers.get('content-type') || '';
  const txt = await req.text();
  if (/json/.test(ct) || /^\s*[{[]/.test(txt)) { try { return JSON.parse(txt); } catch (e) { } }
  const o = {}; try { new URLSearchParams(txt).forEach((v, k) => (o[k] = v)); } catch (e) { }
  return o;
}
// amount in agorot from "₪45.00", "45,00 ₪", 45, "-120.5"
function agorot(v) {
  if (typeof v === 'number') return Math.round(Math.abs(v) * 100);
  const p = numPrice(String(v || '').replace(/[‎‏]/g, ''));
  return p ? Math.round(parseFloat(p) * 100) : 0;
}
async function enqueue(env, items) {
  const inbox = await kvGet(env, 'inbox', []), seen = await kvGet(env, 'seen', []);
  const S = new Set(seen); let added = 0;
  for (const it of items) { if (!it.amt || S.has(it.id)) continue; S.add(it.id); seen.push(it.id); inbox.push(it); added++; }
  if (added) { await kvPut(env, 'inbox', inbox.slice(-500)); await kvPut(env, 'seen', seen.slice(-3000)); }
  return added;
}
async function syncApi(req, env, path) {
  if (!env.WANT_KV || !env.WANT_TOKEN) return JS({ error: 'not_set_up', need: [!env.WANT_KV && 'WANT_KV', !env.WANT_TOKEN && 'WANT_TOKEN'].filter(Boolean) }, 503);
  if (!authed(req, env)) return JS({ error: 'bad_key' }, 401);
  if (path === '/api/ping') return JS({ ok: true, bank: await kvGet(env, 'bank', null) });
  if (path === '/api/state') return JS({ ok: true, bank: await kvGet(env, 'bank', null), inbox: await kvGet(env, 'inbox', []) });
  if (req.method !== 'POST') return JS({ error: 'post_only' }, 405);
  const b = await readBody(req);
  if (path === '/api/ingest') { // Apple Pay automation or quick add from a Shortcut
    const amt = agorot(b.amount), title = String(b.merchant || b.title || '').trim().slice(0, 60);
    if (!amt) return JS({ error: 'no_amount' }, 400);
    const ts = b.date && !isNaN(Date.parse(b.date)) ? Date.parse(b.date) : Date.now();
    const type = b.type === 'inc' ? 'inc' : 'exp', src = b.source === 'quick' ? 'quick' : 'applepay';
    const id = b.id ? String(b.id).slice(0, 80) : 'ap_' + await sha([src, title, amt, Math.floor(ts / 60000)].join('|'));
    const added = await enqueue(env, [{ id, type, amt, ts, title, src, card: String(b.card || '').slice(0, 40) }]);
    return JS({ ok: true, id, duplicate: !added });
  }
  if (path === '/api/bank') { // the Discount script on your computer
    const bal = Number(b.balance);
    if (isFinite(bal)) await kvPut(env, 'bank', { bal: Math.round(bal * 100), at: Date.now(), acct: String(b.accountNumber || '').slice(-4), name: String(b.bankName || 'Bank').slice(0, 30) });
    const items = [];
    for (const x of Array.isArray(b.txns) ? b.txns : []) {
      const a = Number(x.amount); if (!isFinite(a) || !a) continue;
      const ts = Date.parse(x.date) || Date.now();
      const id = 'bk_' + (x.id ? String(x.id) : await sha([x.date, a, x.description].join('|')));
      items.push({ id, type: a < 0 ? 'exp' : 'inc', amt: Math.round(Math.abs(a) * 100), ts, title: String(x.description || '').trim().slice(0, 60), src: 'bank' });
    }
    const added = await enqueue(env, items);
    return JS({ ok: true, added, balance: isFinite(bal) });
  }
  if (path === '/api/ack') {
    const ids = new Set(Array.isArray(b.ids) ? b.ids : []);
    const inbox = await kvGet(env, 'inbox', []);
    const left = inbox.filter(x => !ids.has(x.id));
    if (left.length !== inbox.length) await kvPut(env, 'inbox', left);
    return JS({ ok: true, left: left.length });
  }
  return JS({ error: 'not_found' }, 404);
}


const UA='Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1';
const J=(o,st=200,extra={})=>new Response(JSON.stringify(o),{status:st,headers:Object.assign({'content-type':'application/json; charset=utf-8','access-control-allow-origin':'*','cache-control':'no-store'},extra)});
async function rates(cur){
  const key=new Request('https://want.cache/rates/'+cur);const cache=caches.default;
  let r=await cache.match(key);
  if(!r){const res=await fetch('https://open.er-api.com/v6/latest/'+cur);if(!res.ok)return null;const d=await res.json();if(d.result!=='success')return null;
    r=new Response(JSON.stringify({ils:d.rates.ILS,at:d.time_last_update_utc}),{headers:{'cache-control':'max-age=21600'}});await cache.put(key,r.clone())}
  return r.json();
}
async function product(u){
  let target;try{target=new URL(u)}catch(e){return J({error:'bad_url'},400)}
  if(!/^https?:$/.test(target.protocol))return J({error:'bad_url'},400);
  let res;try{res=await fetch(target.href,{headers:{'user-agent':UA,'accept':'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8','accept-language':'he-IL,he;q=0.9,en-US;q=0.8,en;q=0.7'},redirect:'follow',cf:{cacheTtl:900,cacheEverything:true}})}catch(e){return J({error:'fetch_failed'},502)}
  const html=(await res.text()).slice(0,2000000);
  const d=extract(html,res.url||target.href);
  const blocked=res.status>=400||(!d.price&&!d.image&&/denied|captcha|robot|blocked|forbidden|attention required|just a moment/i.test(d.title));
  if(blocked)return J({error:'blocked',store:d.store});
  if(d.price&&d.currency&&d.currency!=='ILS'){try{const r=await rates(d.currency);if(r&&r.ils){d.priceILS=String(Math.round(parseFloat(d.price)*r.ils*100)/100);d.rateAt=r.at}}catch(e){}}
  return J(d);
}
